#!/usr/bin/env bash
# Restore the paths .aii/manifest.yaml deletes after the round:
#   .venv/  -> rebuilt from the exact pins (requirements.lock.txt == pyproject.toml dependencies)
#   work/   -> C5 residual cache work/c5_hR.npz, regenerated by stage s7 (needs the GPU and Qwen/Qwen3-8B)
# __pycache__/ directories are rebuilt automatically on import.
set -euo pipefail
cd "$(dirname "$0")"
uv venv .venv --python=3.12
uv pip install --python .venv/bin/python -r requirements.lock.txt
if [ "${1:-}" = "--with-c5-cache" ]; then
  .venv/bin/python method.py s7
fi
